/* bs-gestion-social.sql — _BS_GESTION_SOCIAL_V1 (14-nov-2026)
   Tablas del módulo Gestión Social del Trabajador (casos sociales + seguimientos). Nacen directo en Supabase: no tienen hoja de Google.
   Misma forma que las demás tablas bs_* (tablas-hoja: fila, columnas tipadas, otros, actualizado) + tabla de paso __carga.
   Esquema rl explícito. Idempotente (se puede volver a correr).
   Uso: cd C:\sistema-rl-verfrut\migracion ; node aplicar-sql.js bs-gestion-social.sql */
CREATE TABLE IF NOT EXISTS rl."bs_gs_casos" (
  "id_fila" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "fila" integer NOT NULL,
  "id" double precision,
  "codigo" extensions.citext,
  "fecha_deteccion" timestamp,
  "dni" extensions.citext,
  "nombre" extensions.citext,
  "empresa" extensions.citext,
  "fundo" extensions.citext,
  "cargo" extensions.citext,
  "sede" extensions.citext,
  "tipo" extensions.citext,
  "prioridad" extensions.citext,
  "origen" extensions.citext,
  "descripcion" extensions.citext,
  "accion_inmediata" extensions.citext,
  "fecha_programada" timestamp,
  "derivacion" extensions.citext,
  "responsable" extensions.citext,
  "compromisos" extensions.citext,
  "reservado" extensions.citext,
  "estado" extensions.citext,
  "resultado" extensions.citext,
  "fecha_cierre" timestamp,
  "numero_seguimientos" double precision,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "updated_by" extensions.citext,
  "updated_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext,
  "actualizado" timestamp DEFAULT (now() at time zone 'utc') NOT NULL,
  PRIMARY KEY ("id_fila")
);
CREATE UNIQUE INDEX IF NOT EXISTS "ix_bs_gs_casos_ux_bs_gs_casos_fila" ON rl."bs_gs_casos" ("fila");
CREATE TABLE IF NOT EXISTS rl."bs_gs_casos__carga" (
  "fila" integer NOT NULL,
  "id" double precision,
  "codigo" extensions.citext,
  "fecha_deteccion" timestamp,
  "dni" extensions.citext,
  "nombre" extensions.citext,
  "empresa" extensions.citext,
  "fundo" extensions.citext,
  "cargo" extensions.citext,
  "sede" extensions.citext,
  "tipo" extensions.citext,
  "prioridad" extensions.citext,
  "origen" extensions.citext,
  "descripcion" extensions.citext,
  "accion_inmediata" extensions.citext,
  "fecha_programada" timestamp,
  "derivacion" extensions.citext,
  "responsable" extensions.citext,
  "compromisos" extensions.citext,
  "reservado" extensions.citext,
  "estado" extensions.citext,
  "resultado" extensions.citext,
  "fecha_cierre" timestamp,
  "numero_seguimientos" double precision,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "updated_by" extensions.citext,
  "updated_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext
);
CREATE TABLE IF NOT EXISTS rl."bs_gs_seguimientos" (
  "id_fila" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "fila" integer NOT NULL,
  "id" double precision,
  "id_caso" double precision,
  "numero_seguimiento" double precision,
  "fecha_seguimiento" timestamp,
  "tipo" extensions.citext,
  "detalle" extensions.citext,
  "acuerdos" extensions.citext,
  "proxima_fecha" timestamp,
  "ubicacion" extensions.citext,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext,
  "actualizado" timestamp DEFAULT (now() at time zone 'utc') NOT NULL,
  PRIMARY KEY ("id_fila")
);
CREATE UNIQUE INDEX IF NOT EXISTS "ix_bs_gs_seguimientos_ux_bs_gs_seguimientos_fila" ON rl."bs_gs_seguimientos" ("fila");
CREATE TABLE IF NOT EXISTS rl."bs_gs_seguimientos__carga" (
  "fila" integer NOT NULL,
  "id" double precision,
  "id_caso" double precision,
  "numero_seguimiento" double precision,
  "fecha_seguimiento" timestamp,
  "tipo" extensions.citext,
  "detalle" extensions.citext,
  "acuerdos" extensions.citext,
  "proxima_fecha" timestamp,
  "ubicacion" extensions.citext,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext
);
/* Fuente explícita: estas tablas mandan desde Supabase (bs-guardar también lo asume cuando no hay fila) */
INSERT INTO rl.bs_fuente (clave, fuente, por) VALUES ('bs_gs_casos','supabase','_BS_GESTION_SOCIAL_V1'), ('bs_gs_seguimientos','supabase','_BS_GESTION_SOCIAL_V1') ON CONFLICT (clave) DO NOTHING;
